/**
 * How the controller would obtain one pinned file, before it commits to a
 * Run (C12, DS002): already `owned` (verified in the store), from the shared
 * directory by `link` (no new disk space) or by `copy`, or by `download`.
 * A shared candidate is matched by size here and hashed only when it is
 * adopted; `bytesNeeded` is the disk space the chosen way needs.
 */
async function acquisitionWith(fsApi, paths, artifact, keys, adoptFrom) {
    const current = await inspectWith(fsApi, paths, artifact, keys);
    if (current.state === 'complete') return { method: 'owned', bytesNeeded: 0 };
    const remaining = artifact.size - (current.state === 'partial' ? current.bytes : 0);
    for (const source of await sharedCandidates(fsApi, adoptFrom, artifact.size)) {
        // A link that succeeds costs no space; try one into the store and remove it at once.
        const probe = `${paths.partial}.probe-${crypto.randomBytes(6).toString('hex')}`;
