            await fsApi.promises.mkdir(path.dirname(probe), { recursive: true });
            await fsApi.promises.link(source, probe);
            await fsApi.promises.rm(probe, { force: true });
            return { method: 'link', bytesNeeded: 0, from: source };
        } catch {
            await fsApi.promises.rm(probe, { force: true }).catch(() => {});
            return { method: 'copy', bytesNeeded: artifact.size, from: source };
        }
    }
    return { method: 'download', bytesNeeded: remaining };
}

export async function artifactAcquisition({ root, artifact, adoptFrom = [], fsApi = fs }) {
    return acquisitionWith(fsApi, artifactPaths({ root, artifact }), artifact, IDENTITY_KEYS, adoptFrom);
