export async function snapshotFileAcquisition({ root, artifact, adoptFrom = [], fsApi = fs }) {
    return acquisitionWith(fsApi, snapshotFilePaths({ root, artifact }), artifact, SNAPSHOT_IDENTITY_KEYS, adoptFrom);
