1009	    if (typeof root !== 'string' || !root) {
1010	        throw invalidSource('Missing weights root');
1011	    }
1012	    assertRepo(repo);
1013	    if (typeof commit !== 'string' || !COMMIT_RE.test(commit)) {
1014	        throw invalidSource('Invalid snapshot commit');
1015	    }
1016	    const base = path.resolve(root);
1017	    const dir = path.join(base, ...repo.split('/'), commit);
1018	    const stateDir = path.join(base, '.state', ...repo.split('/'), commit);
1019	    assertInside(base, dir);
1020	    assertInside(base, stateDir);
1021	    return { dir, stateDir };
1022	}
