1024	function assertSnapshotArtifact(artifact) {
1025	    if (!artifact || typeof artifact !== 'object') {
1026	        throw invalidSource('Missing artifact');
1027	    }
1028	    if (!isSnapshotFile(artifact.file)) {
1029	        throw invalidSource('Invalid snapshot file name');
1030	    }
1031	    if (!Number.isSafeInteger(artifact.size) || artifact.size <= 0) {
1032	        throw invalidSource('Invalid artifact size');
1033	    }
1034	    const hasSha = artifact.sha256 !== undefined;
1035	    if (hasSha ? !SHA256_RE.test(String(artifact.sha256)) : !GIT_OID_RE.test(String(artifact.gitOid || ''))) {
1036	        throw invalidSource('A snapshot file needs its sha256 or git oid');
1037	    }
1038	}
1039	
1040	function snapshotFilePaths({ root, artifact }) {
1041	    assertSnapshotArtifact(artifact);
1042	    const { dir, stateDir } = snapshotPaths({ root, repo: artifact.repo, commit: artifact.commit });
1043	    const file = path.join(dir, artifact.file);
1044	    const partial = path.join(stateDir, `${artifact.file}.partial`);
1045	    assertInside(dir, file);
1046	    assertInside(stateDir, partial);
1047	    return { dir, file, partial, identity: `${partial}.json`, meta: path.join(stateDir, `${artifact.file}.json`) };
1048	}
1049	
1050	/** One file of a pinned snapshot, resumed, verified and moved into the snapshot directory. */
1051	export async function downloadSnapshotFile({
1052	    artifact,
1053	    root,
1054	    token = '',
1055	    fetchImpl = globalThis.fetch,
1056	    baseUrl = 'https://huggingface.co',
1057	    ...options
1058	}) {
1059	    const paths = snapshotFilePaths({ root, artifact });
1060	    return downloadInto({ paths, artifact, identityKeys: SNAPSHOT_IDENTITY_KEYS, url: null, token, fetchImpl, baseUrl, ...options });
1061	}
1062	
1063	export async function inspectSnapshotFile({ root, artifact }) {
1064	    return inspectWith(fs, snapshotFilePaths({ root, artifact }), artifact, SNAPSHOT_IDENTITY_KEYS);
1065	}
1066	
1067	/**
1068	 * Pin a snapshot: the revision's commit, and every top-level model file at
1069	 * that commit with its size and digest (LFS sha256, or the git blob oid for a
1070	 * file kept in git). Reads metadata only.
1071	 */
1072	export async function resolveHuggingFaceSnapshot({
1073	    repo,
1074	    revision = 'main',
1075	    token = '',
1076	    fetchImpl = globalThis.fetch,
1077	    baseUrl = 'https://huggingface.co',
1078	    timeoutMs = METADATA_TIMEOUT_MS,
1079	}) {
1080	    assertRepo(repo);
1081	    assertRevision(revision);
1082	    const commit = await resolveCommit({ repo, revision, token, fetchImpl, baseUrl, timeoutMs });
1083	    let url = `${baseUrl}/api/models/${encodeSegments(repo)}/tree/${commit}`;
