1086	        const { json, link } = await fetchJson(url, { token, fetchImpl, timeoutMs });
1087	        if (!Array.isArray(json)) {
1088	            throw new DownloadError('RESOLVE_FAILED', 'Hugging Face tree response is not a list');
1089	        }
