1093	                // Never fall back to the pointer's git oid for an LFS file.
1094	                const lfs = lfsIdentity(entry);
1095	                if (!lfs) throw new DownloadError('RESOLVE_FAILED', `Inconsistent LFS metadata for ${entry.path}`, { details: { repo, commit } });
